using UnityEngine;

public class PvpEnemySpawner : MonoBehaviour
{
	private bool isSpawning;

	private EnemyFactory[] enemyFactories;

	private ChaosQuickStopwatch enemyStopwatch = new ChaosQuickStopwatch(5f);

	private ChaosQuickStopwatch diffStopwatch = new ChaosQuickStopwatch(20f);

	private void Awake()
	{
		enemyFactories = GetComponentsInChildren<EnemyFactory>();
	}

	private void Start()
	{
		if (enemyFactories == null || enemyFactories.Length == 0)
		{
			enabled = false;
		}
	}

	private void Update()
	{
		if (GameController.pvpOn)
		{
			if (!isSpawning)
			{
				SetFactoryStatus(givenStatus: true);
				return;
			}
			if (!diffStopwatch.IsRunning)
			{
				diffStopwatch.IsRunning = true;
				GameController.tierCount++;
			}
			if (enemyStopwatch.IsRunning)
			{
				return;
			}
			enemyStopwatch.IsRunning = true;
			EnemyFactory[] array = enemyFactories;
			foreach (EnemyFactory enemyFactory in array)
			{
				if (enemyFactory != null && enemyFactory.AllEnemiesCleared())
				{
					enemyFactory.ResetFactory();
					enemyFactory.spawning = true;
				}
			}
		}
		else if (isSpawning)
		{
			SetFactoryStatus(givenStatus: false);
		}
	}

	private void SetFactoryStatus(bool givenStatus)
	{
		isSpawning = givenStatus;
		enemyStopwatch.IsRunning = givenStatus;
		EnemyFactory[] array = enemyFactories;
		foreach (EnemyFactory enemyFactory in array)
		{
			if (enemyFactory != null)
			{
				enemyFactory.ResetFactory();
				enemyFactory.spawning = givenStatus;
			}
		}
		diffStopwatch.IsRunning = givenStatus;
		GameController.tierCount = 0;
	}

	private void OnDisable()
	{
		GameController.tierCount = 0;
	}
}

