public class FireBombChance : Item
{
	public static string staticID = "FireBombChance";

	private float fireBombChance = 0.1f;

	public FireBombChance()
	{
		ID = staticID;
		category = Category.Offense;
	}

	public override void Activate()
	{
		SetParentAsPlayer();
		if (!(parentPlayer == null))
		{
			Health.globalTakeDamageActualHandlers = (Health.GlobalOnTakeDamageHandler)Delegate.Combine(Health.globalTakeDamageActualHandlers, new Health.GlobalOnTakeDamageHandler(OnTakeDamage));
		}
	}

	public override void Deactivate()
	{
		if (!(parentPlayer == null))
