			Health.globalTakeDamageActualHandlers = (Health.GlobalOnTakeDamageHandler)Delegate.Remove(Health.globalTakeDamageActualHandlers, new Health.GlobalOnTakeDamageHandler(OnTakeDamage));
		}
	}

	public void OnTakeDamage(AttackInfo givenAtkInfo, Entity attackEntity = null, Entity hurtEntity = null)
