using UnityEngine;

public class HorseMaskItem : HeadgearItem
{
	public static string staticID = "HorseMaskItem";

	private static GameObject _prefab;

	public NumVarStatMod speedMod;

	public NumVarStatMod delayMod;

	public static GameObject Prefab
	{
		get
		{
			if (_prefab == null)
			{
				_prefab = ChaosBundle.Get("Assets/Prefabs/Headgear/HorseMask.prefab");
			}
			return _prefab;
		}
	}

	protected override string ExtraInfo => PercentToStr(speedMod, "+");

	public HorseMaskItem()
	{
		ID = staticID;
		category = Category.Defense;
		parentCombineID = UnicornMask.staticID;
		headgearPrefab = Prefab;
		speedMod = new NumVarStatMod(ID, 0.08f, 10, VarStatModType.Multiplicative);
		delayMod = new NumVarStatMod(ID, -0.6f, 10, VarStatModType.Multiplicative);
	}

	public override void Activate()
	{
		if (!(parentEntity == null))
		{
			base.Activate();
			if (parentEntity.inventory.ContainsItem(RainbowTrail.staticID))
			{
				parentEntity.inventory.AddItem(UnicornMask.staticID, showNotice: false, ignoreMax: true);
				parentEntity.inventory.RemoveItem(RainbowTrail.staticID);
				parentEntity.inventory.RemoveItem(staticID);
			}
			else
			{
				SetModStatus(givenStatus: true);
			}
		}
	}

	public override void Deactivate()
	{
		base.Deactivate();
		SetModStatus(givenStatus: false);
	}

	private void SetModStatus(bool givenStatus)
	{
		if (SetParentAsPlayer())
		{
			parentPlayer.movement.moveSpeedStat.Modify(speedMod, givenStatus);
			parentPlayer.runSpeedupStat.Modify(delayMod, givenStatus);
		}
	}
}
