using System;

[Serializable]
public class DialogEntry
{
	public string ID;

	public DialogMessage[] messages;

	private int currentIndex;

	public int CurrentIndex
	{
		get
		{
			return currentIndex;
		}
		set
		{
			if (IsValidIndex(value))
			{
				currentIndex = value;
			}
		}
	}

	public bool ScriptEnd => currentIndex >= messages.Length;

	public DialogEntry(int startingIndex = 0)
	{
		currentIndex = 0;
		if (!IsValidIndex(startingIndex, setIndexIfValid: true))
		{
			currentIndex = -1;
		}
	}

	public void Initialize()
	{
		for (int i = 0; i < messages.Length; i++)
		{
			if (i == 0)
			{
				if (messages[i].showOptions == -1)
				{
					messages[i].showOptions = 0;
				}
				continue;
			}
			messages[i].leftActive = messages[0].leftActive;
			messages[i].rightActive = messages[0].rightActive;
			if (messages[i].showOptions == -1)
			{
				messages[i].showOptions = messages[i - 1].showOptions;
			}
			if (messages[i].leftSpeakerID == null)
			{
				messages[i].leftSpeakerID = messages[i - 1].leftSpeakerID;
			}
			if (messages[i].rightSpeakerID == null)
			{
				messages[i].rightSpeakerID = messages[i - 1].rightSpeakerID;
			}
		}
	}

	public DialogMessage GetMessageAtIndex(int requestedIndex, bool setIndex = false)
	{
		if (IsValidIndex(requestedIndex, setIndex))
		{
			return messages[requestedIndex];
		}
		return null;
	}

	public DialogMessage GetMessage()
	{
		if (IsValidIndex(currentIndex))
		{
			currentIndex++;
			return messages[currentIndex - 1];
		}
		return null;
	}

	public void Reset()
	{
		ResetToIndex(0);
	}

