using System;
using System.Collections;
using UnityEngine;

public class DamageUpWithGold : Item
{
	public static string staticID = "DamageUpWithGold";

	private static float damagePerGold = 0.0004f;

	private static float damageMax = 0.2f;

	private NumVarStatMod damageMod;

	private ChaosQuickStopwatch waitStopwatch = new ChaosQuickStopwatch();

	protected override string ExtraInfo => PercentToStr(damageMod, "+");

	public DamageUpWithGold()
	{
		ID = staticID;
		category = Category.Offense;
		parentGroupID = GoldGroupItem.staticID;
		damageMod = new NumVarStatMod(ID, 0f, 10, VarStatModType.Multiplicative);
	}

	public override void Activate()
	{
		SetEventHandlers(givenStatus: true);
	}

	public override void Deactivate()
	{
		SetEventHandlers(givenStatus: false);
	}

	private void SetEventHandlers(bool givenStatus)
	{
		if (!givenStatus || !GroupItemCreated(GoldGroupItem.staticID))
		{
			StatManager.ModifyAllStatData(damageMod, parentSkillCategory, StatData.damageStr, IgnoreStatusConditional, givenStatus);
			OnGoldChange();
			GoldWallet goldWallet = Player.goldWallet;
			goldWallet.depositEventHandlers = (Wallet.DepositEventHandler)Delegate.Remove(goldWallet.depositEventHandlers, new Wallet.DepositEventHandler(OnGoldChange));
			GoldWallet goldWallet2 = Player.goldWallet;
			goldWallet2.withdrawEventHandlers = (Wallet.WithdrawEventHandler)Delegate.Remove(goldWallet2.withdrawEventHandlers, new Wallet.WithdrawEventHandler(OnGoldChange));
			if (givenStatus)
			{
				GoldWallet goldWallet3 = Player.goldWallet;
				goldWallet3.depositEventHandlers = (Wallet.DepositEventHandler)Delegate.Combine(goldWallet3.depositEventHandlers, new Wallet.DepositEventHandler(OnGoldChange));
				GoldWallet goldWallet4 = Player.goldWallet;
				goldWallet4.withdrawEventHandlers = (Wallet.WithdrawEventHandler)Delegate.Combine(goldWallet4.withdrawEventHandlers, new Wallet.WithdrawEventHandler(OnGoldChange));
			}
		}
	}

	private void OnGoldChange(int givenValue = 0)
	{
		if (!waitStopwatch.IsRunning && parentEntity != null && parentEntity.gameObject != null && parentEntity.gameObject.activeSelf)
		{
			parentEntity.StartCoroutine(QueueUpdateDamage());
		}
	}

	private IEnumerator QueueUpdateDamage()
	{
		if (!waitStopwatch.IsRunning)
		{
			waitStopwatch.IsRunning = true;
			while (waitStopwatch.IsRunning)
			{
				yield return null;
			}
			damageMod.modValue = Mathf.Min(damageMax, (float)Player.goldWallet.balance * damagePerGold);
		}
	}
}
